# shellcheck shell=bash
# Shared helpers for the Gitea / Forgejo adapter — sourced by every verb script.
# GENERATED by /work-items:onboard-adapter from templates/common.sh.tmpl. This file
# is yours now: it lands in your repo, under your review and CI. Regenerating
# overwrites it, so keep provider-specific logic in the verb scripts.
#
# Contract: tools/work-item-tracker/CONTRACT.md ("Adapter contract", "JSON output
# contract", "Exit codes"). Auth: a Gitea / Forgejo API token sent as `Authorization: token <token>` — the credential is read from
# the env var NAMED BY config.gitea.auth_env, never stored in the tracked
# binding, and passed to curl through a stdin config (-K -) so it never appears in
# argv (visible to every other process on the machine via /proc and `ps`).
# HTTP goes through ${WIT_GITEA_CURL:-curl}; tests inject a mock binary
# there to exercise the read path offline.

[[ -n "${_WIT_GITEA_COMMON_LOADED:-}" ]] && return 0
readonly _WIT_GITEA_COMMON_LOADED=1

WIT_GITEA_ADAPTER_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
readonly WIT_GITEA_ADAPTER_DIR

# Seam libraries. This adapter lives in the CONSUMING repo while the engine
# dispatching it lives in the read-only plugin directory, so its own ../../lib may
# not exist at all. The dispatcher exports WIT_SEAM_LIB_DIR (CONTRACT.md "Adapter
# resolution") naming the lib/ of the engine actually dispatching — and the engine
# whose contract version this adapter's manifest just handshook against. Fall back
# to the relative path for a vendored seam or a direct (non-dispatched) run. A
# missing lib is a hard failure with a clear diagnostic (exit 3 — setup/config),
# never a silent sourcing failure leaving a verb emitting a malformed record. Runs
# before the EX_* constants below exist, so it uses the literal.
WIT_GITEA_SEAM_LIB="${WIT_SEAM_LIB_DIR:-$WIT_GITEA_ADAPTER_DIR/../../lib}"
readonly WIT_GITEA_SEAM_LIB

wit_gitea_require_seam_lib() {
  [[ -f "$1" ]] && return 0
  printf 'work-item-tracker gitea adapter: required seam library not found: %s\n' "$1" >&2
  printf '  set WIT_SEAM_LIB_DIR to the work-item-tracker lib/ directory, or vendor the seam\n' >&2
  exit 3
}

# The `shellcheck source=` hints name the RELATIVE seam path rather than /dev/null:
# where a vendored or bundled seam sits there, ShellCheck follows it and every
# WIT_ID_* / WIT_SCHEMA_VERSION reference in this adapter's verb scripts resolves.
# Where it does not (a consumer-local adapter beside no vendored seam), ShellCheck
# resolves. Where it does not, SC1091 is disabled so the absence is quiet rather than
# an info per source line — the runtime check above is what actually enforces presence.
wit_gitea_require_seam_lib "$WIT_GITEA_SEAM_LIB/id.sh"
# shellcheck source=../../lib/id.sh disable=SC1091
source "$WIT_GITEA_SEAM_LIB/id.sh"
wit_gitea_require_seam_lib "$WIT_GITEA_SEAM_LIB/json.sh"
# shellcheck source=../../lib/json.sh disable=SC1091
source "$WIT_GITEA_SEAM_LIB/json.sh"
# binding.sh is sourced, not inherited: the dispatcher runs each verb as a fresh
# `bash <verb>.sh` subprocess, so only exported env vars cross — not wit_find_binding.
# The adapter re-locates the binding itself to read its own config subtree.
wit_gitea_require_seam_lib "$WIT_GITEA_SEAM_LIB/binding.sh"
# shellcheck source=../../lib/binding.sh disable=SC1091
source "$WIT_GITEA_SEAM_LIB/binding.sh"

readonly EX_INTERNAL=1
readonly EX_USAGE=2
readonly EX_CONFIG=3
readonly EX_AUTH=4
readonly EX_NOT_FOUND=5
readonly EX_CONFLICT=7
readonly EX_UNAVAILABLE=8

# HTTP command indirection: the sole testability seam. Tests point
# WIT_GITEA_CURL at a mock returning canned responses, keeping every
# verb path offline. Absent → real curl.
readonly WIT_GITEA_CURL_BIN="${WIT_GITEA_CURL:-curl}"

# config.gitea.host becomes the request host that RECEIVES the credential,
# so it must be a BARE hostname — no scheme, path, userinfo (`@`), port, or control
# characters — lest a binding smuggle URL structure that redirects the token off the
# intended tenant. A tracked binding is PR-modifiable and the token may be present in
# CI, so host is additionally pinned by SUFFIX where a pin exists.
#
# The effective pin is, in order: config.gitea.host_suffix from the binding
# (the consumer's own pin — the override seam), else the generated default below. A
# non-empty pin denies by default; config.gitea.allow_custom_domain=true is
# the explicit, diffable opt-out. An EMPTY generated default means this provider is
# self-hosted and has no vendor domain to pin against — the consumer can still pin
# their own instance via the binding key, and the adapter README records that as a
# stated posture rather than leaving it implied.
readonly WIT_GITEA_HOSTNAME_RE='^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$'
readonly WIT_GITEA_DEFAULT_HOST_SUFFIX=''
# auth_env is dereferenced via ${!name}; an invalid identifier aborts bash, so it
# must be a valid shell variable name.
readonly WIT_GITEA_ENV_NAME_RE='^[A-Za-z_][A-Za-z0-9_]*$'
# Scope entries are interpolated into request paths and/or query strings, so they are
# constrained to an allowlist BEFORE interpolation. Allowlisting (reject the
# unexpected) is safer than escaping: an escaping bug is silent, a rejection is loud.
readonly WIT_GITEA_SCOPE_RE='^[A-Za-z0-9][A-Za-z0-9._-]*/[A-Za-z0-9][A-Za-z0-9._-]*$'

# Per-page request size. A stock Gitea caps a page at api.MAX_RESPONSE_ITEMS = 50; the
# adapter always sends an explicit `limit`, because an omitted one falls back to
# api.DEFAULT_PAGING_NUM = 30 and truncates silently — the same trap the contract calls
# out for `gh`. Overridable per instance via config.gitea.page_size.
readonly WIT_GITEA_DEFAULT_PAGE_SIZE=50
# The total this adapter will page up to, matching limits.list_items_max in
# capabilities.json. Kept in sync deliberately: the manifest is what callers read, this
# is what the code enforces, and a conformance case asserts they agree.
# shellcheck disable=SC2034  # read by list-items.sh; this file is sourced-only
readonly WIT_GITEA_LIST_ITEMS_MAX=1000

# Set by wit_gitea_http; declared here so a read before the first call
# does not trip `set -u`.
WIT_GITEA_BODY=""
WIT_GITEA_STATUS=""

wit_usage_error() {
  printf '%s: %s\n' "$(basename "${BASH_SOURCE[1]}")" "$1" >&2
  exit "$EX_USAGE"
}

# wit_gitea_unimplemented <verb> — the marker a freshly generated verb
# script carries until its provider mapping is filled in. Exit 1 (internal), NOT 6:
# exit 6 means "this provider cannot do it and the manifest says so", which is a
# permanent, honest degradation the caller may route around. An unfilled scaffold is
# neither — declaring it 6 would launder unfinished work as a provider limitation, and
# the conformance suite would pass on a verb that does nothing. Any verb still
# reaching this line either needs its mapping written or needs `false` in
# capabilities.json.
wit_gitea_unimplemented() {
  printf '%s: gitea adapter verb %s is a generated scaffold with no provider mapping yet\n' \
    "$(basename "${BASH_SOURCE[1]}")" "$1" >&2
  printf '  fill in its PROVIDER MAPPING block, or set verbs["%s"]=false in capabilities.json\n' "$1" >&2
  exit "$EX_INTERNAL"
}

# wit_help_if_requested <usage-text> <args…> — print usage + exit 0 on --help.
wit_help_if_requested() {
  local usage="$1"
  shift
  if [[ "${1:-}" == "--help" ]]; then
    printf '%s\n' "$usage"
    exit 0
  fi
}

# wit_gitea_nonempty_array <json-text> — 0 when the text is a non-empty
# JSON array. Type is checked before length so a scalar such as "scopes":"abc" cannot
# pass on its string length; jq's `and` short-circuits, so `length` never runs on a
# non-array.
wit_gitea_nonempty_array() {
  [[ "$(jq -r 'if (type == "array" and length > 0) then "yes" else "no" end' <<<"$1")" == "yes" ]]
}

# wit_gitea_bad_elements <anchored-regex> <json-array> — the array's
# elements that are not strings matching the allowlist, as a JSON array (`[]` when all
# are valid). The type guard sits left of the `or` so test() never runs on a
# non-string. Checked IN jq rather than a bash line-loop: command substitution strips
# trailing newlines, so `[""]` would evade a loop.
wit_gitea_bad_elements() {
  jq -rc --arg re "$1" '[.[] | select((type != "string") or (test($re) | not))]' <<<"$2"
}

# wit_require_gitea_id <id> — parse an ID and require its provider be
# `gitea`. The shared grammar accepts any provider; this adapter rejects
# foreign-provider IDs so a `github:…#N` never operates on a Gitea / Forgejo item.
# Sets the WIT_ID_* globals.
# shellcheck disable=SC2154  # WIT_ID_PROVIDER is exported by wit_parse_id in the seam's id.sh, sourced above through a runtime-resolved path ShellCheck cannot follow
wit_require_gitea_id() {
  wit_parse_id "$1" || return 1
  [[ "$WIT_ID_PROVIDER" == "gitea" ]] || return 1
}

# wit_need_gitea_config — load and validate the gitea config
# subtree from the binding. Call AFTER arg parsing, so --help and usage errors stay
# offline and config-free. Exits 3 on any missing or invalid key.
# Exports WIT_GITEA_HOST, WIT_GITEA_SCOPES (JSON array),
# WIT_GITEA_AUTH_ENV.
wit_need_gitea_config() {
  local name binding ejson
  name="$(basename "${BASH_SOURCE[1]}")"
  binding="$(wit_find_binding)" ||
    {
      printf '%s: no binding found (.work-item-tracker.json) — see CONTRACT.md Setup\n' "$name" >&2
      exit "$EX_CONFIG"
    }
  ejson="$(wit_effective_binding_json "$binding")" ||
    {
      printf '%s: invalid binding at %s — see CONTRACT.md Setup\n' "$name" "$binding" >&2
      exit "$EX_CONFIG"
    }
  WIT_GITEA_HOST="$(jq -r '.config.gitea.host // empty' <<<"$ejson")"
  WIT_GITEA_AUTH_ENV="$(jq -r '.config.gitea.auth_env // empty' <<<"$ejson")"
  WIT_GITEA_SCOPES="$(jq -c '.config.gitea.scopes // []' <<<"$ejson")"
  # Gitea caps one page at api.MAX_RESPONSE_ITEMS and defaults an unspecified `limit`
  # to api.DEFAULT_PAGING_NUM (50 and 30 in a stock instance) — both instance settings,
  # and neither readable through the API. So the page size is config, not a constant:
  # an instance with a lower cap silently returns fewer rows than asked, and one with a
  # higher cap can be paged more efficiently. Read by presence, not `//`, so an explicit
  # null or false is judged below rather than collapsing into the default.
  if [[ "$(jq -r '.config.gitea | has("page_size")' <<<"$ejson")" == "true" ]]; then
    WIT_GITEA_PAGE_SIZE="$(jq -r '.config.gitea.page_size' <<<"$ejson")"
  else
    WIT_GITEA_PAGE_SIZE="$WIT_GITEA_DEFAULT_PAGE_SIZE"
  fi

  local allow_custom_domain host_suffix
  allow_custom_domain="$(jq -r '.config.gitea.allow_custom_domain // false' <<<"$ejson")"
  host_suffix="$(jq -r --arg d "$WIT_GITEA_DEFAULT_HOST_SUFFIX" '.config.gitea.host_suffix // $d' <<<"$ejson")"

  local missing=""
  [[ -n "$WIT_GITEA_HOST" ]] || missing+=" config.gitea.host"
  [[ -n "$WIT_GITEA_AUTH_ENV" ]] || missing+=" config.gitea.auth_env"

  # scopes must be a non-empty ARRAY, not merely truthy: a scalar such as
  # "scopes":"acme/webapp" would satisfy a bare `length > 0` on its string length,
  # then `.[]`/`map(...)` would jq-error into an empty clause this non-`set -e`
  # script would otherwise ignore.
  wit_gitea_nonempty_array "$WIT_GITEA_SCOPES" ||
    missing+=" config.gitea.scopes[](non-empty array)"
  if [[ -n "$missing" ]]; then
    printf '%s: gitea binding missing/invalid required config:%s — see the adapter README\n' "$name" "$missing" >&2
    exit "$EX_CONFIG"
  fi

  # Value-level validation (all exit 3): the credential-bearing host, the token env
  # var name, and every interpolated scope entry against its allowlist charset.
  local bad=""
  if ! [[ "$WIT_GITEA_HOST" =~ $WIT_GITEA_HOSTNAME_RE ]]; then
    bad+=" host:'$WIT_GITEA_HOST'(not a bare hostname)"
  elif [[ -n "$host_suffix" && "$allow_custom_domain" != "true" &&
    "$WIT_GITEA_HOST" != *"$host_suffix" ]]; then
    bad+=" host:'$WIT_GITEA_HOST'(not under $host_suffix; set config.gitea.allow_custom_domain=true to allow)"
  fi
  [[ "$WIT_GITEA_AUTH_ENV" =~ $WIT_GITEA_ENV_NAME_RE ]] ||
    bad+=" auth_env:'$WIT_GITEA_AUTH_ENV'(not a valid env var name)"
  local bad_scopes
  bad_scopes="$(wit_gitea_bad_elements "$WIT_GITEA_SCOPE_RE" "$WIT_GITEA_SCOPES")"
  [[ "$bad_scopes" == "[]" ]] || bad+=" scopes:$bad_scopes"
  # page_size lands in a query string and bounds every paging loop. A non-integer or
  # zero value would either inject or spin forever, so it is validated, not coerced.
  [[ "$WIT_GITEA_PAGE_SIZE" =~ ^[1-9][0-9]*$ ]] ||
    bad+=" page_size:'$WIT_GITEA_PAGE_SIZE'(must be a positive integer)"
  if [[ -n "$bad" ]]; then
    printf '%s: invalid gitea config value(s):%s — see the adapter README\n' "$name" "$bad" >&2
    exit "$EX_CONFIG"
  fi

  # curl is the only prerequisite binary; gate here (exit 3, actionable) rather than
  # let the first request fail obscurely. The bin is the real curl by default or a
  # test-injected mock — either way it must resolve.
  command -v "$WIT_GITEA_CURL_BIN" >/dev/null 2>&1 ||
    {
      printf '%s: prerequisite missing: curl (Gitea / Forgejo REST over HTTPS) — see CONTRACT.md Prerequisites\n' "$name" >&2
      exit "$EX_CONFIG"
    }
  export WIT_GITEA_HOST WIT_GITEA_AUTH_ENV WIT_GITEA_SCOPES WIT_GITEA_PAGE_SIZE
}

# wit_gitea_scope_in_scope <entry> — 0 when the entry is in the binding's
# config.gitea.scopes. That list is the declared read scope AND the
# authorization boundary: a bound workflow must not read items from a scope it did not
# declare, even when the token can see them. Each verb enforces it BEFORE any request,
# mapping a miss to its own usage error (exit 2) so the diagnostic names the verb.
wit_gitea_scope_in_scope() {
  [[ "$(jq -r --arg k "$1" 'if (index($k) != null) then "in" else "out" end' <<<"$WIT_GITEA_SCOPES")" == "in" ]]
}

# wit_gitea_token — echo the credential from the env var NAMED BY
# config.gitea.auth_env. Exits 4 (auth) when that env var is unset or empty:
# the token is never stored in the tracked binding, only referenced by name. Call
# after wit_need_gitea_config.
wit_gitea_token() {
  local token="${!WIT_GITEA_AUTH_ENV:-}"
  if [[ -z "$token" ]]; then
    printf '%s: gitea credential env var %s is unset or empty (config.gitea.auth_env)\n' \
      "$(basename "${BASH_SOURCE[1]}")" "$WIT_GITEA_AUTH_ENV" >&2
    exit "$EX_AUTH"
  fi
  printf '%s' "$token"
}

# wit_gitea_auth_header — the Authorization header line. Built here and fed
# to curl through the stdin config, so the credential never reaches argv.
wit_gitea_auth_header() {
  local token
  token="$(wit_gitea_token)" || exit "$?"
  printf 'Authorization: token %s' "$token"
}

# wit_gitea_http <method> <path> [<json-body>] — call
# https://<host>/api/v1<path>. The Authorization header is fed through curl's
# stdin config (-K -) so the credential never appears in argv. `--proto '=https'`
# refuses any non-HTTPS scheme, and redirects are NOT followed (no -L), so the header
# can never be replayed to a host the binding did not authorize. Captures the response
# body to WIT_GITEA_BODY and the HTTP status to
# WIT_GITEA_STATUS; on a curl transport failure (no status) exits 8.
# HTTP-status→exit-code mapping is left to the caller via
# wit_gitea_require_ok so it can attach verb-specific context.
wit_gitea_http() {
  local method="$1" path="$2" body="${3:-}"
  local url="https://$WIT_GITEA_HOST/api/v1$path"
  local auth raw rc
  auth="$(wit_gitea_auth_header)" || exit "$?"
  local curl_args=(-sS -X "$method" -H "Accept: application/json" --proto '=https' -w $'\n%{http_code}' -K -)
  if [[ -n "$body" ]]; then
    curl_args+=(-H "Content-Type: application/json" --data "$body")
  fi
  raw="$(printf 'header = "%s"\nurl = "%s"\n' "$auth" "$url" |
    "$WIT_GITEA_CURL_BIN" "${curl_args[@]}" 2>/dev/null)"
  rc=$?
  if ((rc != 0)); then
    printf 'gitea: request to %s failed (curl exit %s) — network or endpoint unavailable\n' "$path" "$rc" >&2
    exit "$EX_UNAVAILABLE"
  fi
  WIT_GITEA_STATUS="${raw##*$'\n'}"
  WIT_GITEA_BODY="$(printf '%s' "${raw%$'\n'*}" | wit_strip_cr)"
}

# wit_gitea_require_ok <context> — map WIT_GITEA_STATUS to a
# contract exit code, printing the provider's error text to stderr on failure. 2xx
# returns 0.
wit_gitea_require_ok() {
  local ctx="$1" code="$WIT_GITEA_STATUS"
  case "$code" in
  2*) return 0 ;;
  401 | 403)
    printf 'gitea: %s — authentication/authorization failed (HTTP %s)\n' "$ctx" "$code" >&2
    exit "$EX_AUTH"
    ;;
  404)
    printf 'gitea: %s — not found (HTTP 404)\n' "$ctx" >&2
    exit "$EX_NOT_FOUND"
    ;;
  400)
    # Gitea's only documented 400 on the paths this adapter uses is a cross-repo
    # dependency refused because ALLOW_CROSS_REPOSITORY_DEPENDENCIES is off on the
    # instance (routers/api/v1/repo/issue_dependency.go). It defaults to true, so this
    # is a configuration fact about the instance, not a bug in the request — say which
    # so the operator knows where to look. Anything else 400 stays generic.
    if [[ "$WIT_GITEA_BODY" == *"CrossRepositoryDependencies not enabled"* ]]; then
      printf 'gitea: %s — this instance has ALLOW_CROSS_REPOSITORY_DEPENDENCIES disabled, so a dependency edge cannot cross repositories (HTTP 400)\n' "$ctx" >&2
    else
      printf 'gitea: %s — request rejected (HTTP 400): %s\n' "$ctx" "$WIT_GITEA_BODY" >&2
    fi
    exit "$EX_CONFLICT"
    ;;
  # 423 is Gitea's repo-archived / locked response on the write paths.
  409 | 412 | 422 | 423)
    printf 'gitea: %s — conflict/precondition (HTTP %s)\n' "$ctx" "$code" >&2
    exit "$EX_CONFLICT"
    ;;
  429)
    printf 'gitea: %s — rate limited (HTTP 429); retry later\n' "$ctx" >&2
    exit "$EX_UNAVAILABLE"
    ;;
  5*)
    printf 'gitea: %s — server error (HTTP %s)\n' "$ctx" "$code" >&2
    exit "$EX_UNAVAILABLE"
    ;;
  *)
    printf 'gitea: %s — unexpected response (HTTP %s): %s\n' "$ctx" "$code" "$WIT_GITEA_BODY" >&2
    exit "$EX_INTERNAL"
    ;;
  esac
}

# wit_gitea_normalize_program — a jq program mapping ONE raw Gitea `Issue` into the
# seam's normalized item object (CONTRACT.md "JSON output contract"). Expects jq args
# $sv (schema version) and $bbc (this item's open-blocker count, computed by the caller
# — see wit_gitea_blocked_by_count for why it cannot be derived from the Issue itself).
#
# Field names verified against the Gitea `Issue` struct (modules/structs/issue.go) and
# the generated swagger definition, not from memory:
#   • `state` is already the seam's vocabulary — StateType is exactly "open"|"closed" —
#     so this is the rare provider needing no state mapping table. The `if` still pins
#     it, because an unexpected third value must not pass through unnormalized.
#   • `number` is the repo-scoped index (Go field Index), NOT the global `id`. The
#     contract's ID is the human-facing number, and `id` would produce IDs that no URL
#     resolves.
#   • `repository.full_name` is "owner/repo" — exactly the two path segments the ID
#     grammar wants. The instance HOST is deliberately not part of the ID: one binding
#     addresses one host, and putting it in the ID would break every persisted ID the
#     day an instance moves.
#   • Gitea has NO issue-type registry and NO parent/sub-issue field on Issue, so
#     `type` and `parent_id` are structurally null here — not "unmapped".
# shellcheck disable=SC2016,SC2034  # jq program — $sv/$bbc are jq args, not bash; used by verb scripts
readonly WIT_GITEA_NORMALIZE_PROGRAM='
  def qualify(n): "gitea:" + (.repository.full_name // "") + "#" + (n | tostring);
  {
    schema_version: $sv,
    id: qualify(.number),
    title: (.title // ""),
    state: (if (.state) == "closed" then "closed" else "open" end),
    assignees: [ (.assignees // [])[] | .login // empty ],
    labels: [ (.labels // [])[] | .name // empty ],
    type: null,
    blocked_by_count: $bbc,
    parent_id: null,
    url: (.html_url // "")
  }'

# wit_gitea_blocked_by_count <owner> <repo> <index> — echo the number of OPEN issues
# blocking that issue.
#
# Gitea's Issue object carries no dependency data at all, so this is a separate request
# per item — `GET /issues/{index}/dependencies`, documented as "all issues that block
# this issue". That is the direction the contract wants; the sibling `/blocks` endpoint
# is the same edge read from the other end and would invert the meaning.
#
# The response is a full Issue array, so each blocker's own state comes back inline and
# no second round-trip per blocker is needed. Only OPEN blockers count: counting closed
# ones would keep an item off the frontier forever, since a blocker that was resolved
# would still hold it back.
#
# COST: one extra request per item, including inside list-items. There is no bulk
# dependency endpoint, so this is inherent to the provider rather than a shortcut not
# taken — see this adapter's README.
wit_gitea_blocked_by_count() {
  local owner="$1" repo="$2" index="$3" page=1 total=0 got
  while :; do
    wit_gitea_http GET "/repos/$owner/$repo/issues/$index/dependencies?page=$page&limit=$WIT_GITEA_PAGE_SIZE"
    # A repo with the dependencies unit disabled answers 404 here while the issue
    # itself exists. Treat that as "no dependency edges are visible", not as a missing
    # issue: reporting the ITEM as not-found because a repo unit is off would be a lie
    # about the item.
    if [[ "$WIT_GITEA_STATUS" == "404" ]]; then
      printf '0'
      return 0
    fi
    wit_gitea_require_ok "listing dependencies of $owner/$repo#$index"
    got="$(jq 'length' <<<"$WIT_GITEA_BODY" 2>/dev/null)" || got=0
    total=$((total + $(jq '[.[] | select(.state != "closed")] | length' <<<"$WIT_GITEA_BODY" 2>/dev/null || echo 0)))
    # A short page is the last page. Gitea sends no total-count header on this endpoint.
    ((got < WIT_GITEA_PAGE_SIZE)) && break
    page=$((page + 1))
    # The same overall bound list-items uses, so a pathological dependency graph cannot
    # make one item's count run unbounded.
    ((page * WIT_GITEA_PAGE_SIZE > WIT_GITEA_LIST_ITEMS_MAX)) && break
  done
  printf '%s' "$total"
}

# wit_gitea_scope_parts <owner/repo> — split a scope entry, setting WIT_GITEA_OWNER and
# WIT_GITEA_REPO. The entry has already passed WIT_GITEA_SCOPE_RE, which guarantees
# exactly one slash and no path-traversal characters, so this split is safe to
# interpolate into a request path.
# shellcheck disable=SC2034  # WIT_GITEA_OWNER/REPO are read by the sourcing verb scripts, not within this lib
wit_gitea_scope_parts() {
  WIT_GITEA_OWNER="${1%%/*}"
  WIT_GITEA_REPO="${1#*/}"
}
